<script lang="ts">import {page} from '$app/stores';import {goto} from '$app/navigation';import Heading from '$lib/components/Heading.svelte';import Status from '$lib/components/Status.svelte';import Icon from '$lib/components/Icon.svelte';import MailPassword from '$lib/components/mail/MailPassword.svelte';import WebmailLink from '$lib/components/mail/WebmailLink.svelte';import {mailState,mailReady,mailStorageError,mailCommand} from '$lib/mail/store';import {address,quotas,type Command} from '$lib/mail/model.js';let edit=false,rotate=false,reply=false,label='',quota=5,password='',replyEnabled=false,replyBody='',confirm='',error='',notice='';$: m=$mailState.mailboxes.find(x=>x.id===$page.params.id);function run(c:Command,message:string){try{mailCommand(c);notice=message;error='';return true;}catch(e){error=e instanceof Error?e.message:'Could not save changes.';return false;}}function changePassword(){if(!m)return;if(password.length<8||password.length>128){error='Enter an 8–128 character sample password.';return;}if(run({type:'rotate',id:m.id},'Sample password changed. No credentials were stored.')){password='';rotate=false;}}function remove(){if(!m||confirm!==address(m))return;if(run({type:'delete-mailbox',id:m.id},'Mailbox removed.'))void goto('/email');}</script>
{#if !$mailReady}<p class="subtitle">Loading mailbox…</p>{:else if $mailStorageError}<p role="alert">{$mailStorageError}</p>{:else if m}<Heading title={address(m)} subtitle="Manage this mailbox."><Status value={m.suspended?'Suspended':$mailState.dns[m.domain]?'Configured (demo)':'DNS pending'}/></Heading><div class="stack">{#if error}<p class="error" role="alert">{error}</p>{/if}{#if notice}<p class="subtitle" role="status">{notice}</p>{/if}<section class="card stack"><div class="row between wrap"><div class="row"><span class="icon-box"><Icon name="Email"/></span><div><h3>Mailbox settings</h3><small>{m.domain}</small></div></div><WebmailLink mailbox={m} primary={true} label="Open webmail"/></div><div class="summary-list"><div><span>Email address</span><strong>{address(m)}</strong></div><div><span>Mailbox quota</span><strong>{m.quota} GB</strong></div><div><span>Status</span><strong>{m.suspended?'Suspended':'Enabled (demo)'}</strong></div><div><span>Mail DNS</span><strong>{$mailState.dns[m.domain]?'Example checked':'Not checked'}</strong></div></div><div class="row wrap"><button class="btn secondary" on:click={()=>{if(m){label=m.label;quota=m.quota;edit=!edit;}}}>Edit mailbox</button><button class="btn secondary" on:click={()=>{rotate=!rotate;password='';}}>Change password</button><button class="btn secondary" on:click={()=>{if(m&&window.confirm((m.suspended?'Enable':'Suspend')+' this sample mailbox?'))run({type:'suspend',id:m.id,value:!m.suspended},'Mailbox status updated.');}}>{m.suspended?'Enable mailbox':'Suspend mailbox'}</button></div>{#if edit}<form class="well stack" on:submit|preventDefault={()=>{if(m&&run({type:'edit',id:m.id,label,quota},'Mailbox settings saved.'))edit=false;}}><label class="field">Display label<input bind:value={label} maxlength="100"/></label><label class="field">Quota<select bind:value={quota}>{#each quotas as q}<option value={q}>{q} GB</option>{/each}</select></label><div class="native-actions"><button class="btn secondary" type="button" on:click={()=>edit=false}>Cancel</button><button class="btn primary" type="submit">Save changes</button></div></form>{/if}{#if rotate}<form class="well stack" on:submit|preventDefault={changePassword}><MailPassword bind:value={password} inputId="mail-rotate"/><small>Sample password only; no authentication credentials are stored.</small><div class="native-actions"><button class="btn secondary" type="button" on:click={()=>{rotate=false;password='';}}>Cancel</button><button class="btn primary" type="submit">Change password</button></div></form>{/if}</section><section class="card stack"><div><h3>Connect an email client</h3><p class="subtitle">Example settings for Outlook, Apple Mail and mobile mail. These endpoints are not live.</p></div><div class="grid2">{#each [['Incoming mail · IMAP','993','TLS'],['Outgoing mail · SMTP','587','STARTTLS']] as row}<div class="well"><strong>{row[0]}</strong><div class="summary-list"><div><span>Server</span><strong class="native-path">mail.{m.domain}</strong></div><div><span>Port</span><strong>{row[1]}</strong></div><div><span>Encryption</span><strong>{row[2]}</strong></div></div></div>{/each}</div><div class="setting-row"><span>Username</span><span class="mono native-path">{address(m)}</span></div></section><section class="card stack"><div class="row between wrap"><div><h3>Automatic reply</h3><p class="subtitle">{m.replyEnabled?'Enabled (demo)':'Disabled'}</p></div><button class="btn secondary" on:click={()=>{if(m){replyEnabled=m.replyEnabled;replyBody=m.replyBody;reply=!reply;}}}>Configure</button></div>{#if reply}<form class="stack" on:submit|preventDefault={()=>{if(m&&run({type:'autoreply',id:m.id,enabled:replyEnabled,body:replyBody},'Automatic reply settings saved.'))reply=false;}}><label class="check"><input type="checkbox" bind:checked={replyEnabled}/> Enable automatic reply</label><label class="field">Reply message<textarea rows="5" maxlength="10000" bind:value={replyBody}></textarea></label><small>No actual automated replies are sent.</small><div><button class="btn primary" type="submit">Save settings</button></div></form>{/if}</section><section class="card stack"><h3>Remove mailbox</h3><p class="subtitle">Deletes this sample mailbox and its local messages.</p><label class="field">Type {address(m)} to confirm<input bind:value={confirm}/></label><div><button class="btn danger" disabled={confirm!==address(m)} on:click={remove}>Delete mailbox</button></div></section></div>{:else}<Heading title="Mailbox not found" subtitle="The mailbox may have been removed."/><a class="btn secondary" href="/email">All mailboxes</a>{/if}
